#!/bin/bash
square() { echo $(( $1 * $1 )); }
export -f square
echo "1 2 3 4" | tr ' ' '\n' | xargs -I {} bash -c 'square {}'

#!/bin/bash
declare -A memo
fib() {
  local n=$1
  if [ $n -le 1 ]; then echo $n; return; fi
  if [ -n "${memo[$n]}" ]; then echo ${memo[$n]}; return; fi
  local a=$(fib $((n-1)))
  local b=$(fib $((n-2)))
  memo[$n]=$((a+b))
  echo ${memo[$n]}
}
fib 10

