#!/bin/bash
# طابور: نضيف في النهاية ونزيل من البداية
queue=(); head=0
enqueue() { queue+=("$1"); }
dequeue() { head=$((head+1)); }
enqueue "a"; enqueue "b"; enqueue "c"
echo "Front: ${queue[$head]}"
dequeue
echo "After dequeue: ${queue[@]:$head}"

#!/bin/bash
# لماذا: توضيح أن المتغير المحلي لا يؤثر على العام
var="global"
change() {
    local var="local"
    echo "Inside: $var"
}
change
echo "Outside: $var"

#!/bin/bash
# مكدس: نستخدم مصفوفة ونحاكي الدفع والسحب
stack=()
push() { stack+=("$1"); }
pop() { unset 'stack[${#stack[@]}-1]'; }
push 5; push 7; push 9
echo "Top: ${stack[-1]}"
pop
echo "After pop: ${stack[@]}"
